local mainMod = "SUPER"
local sharedMod = "CTRL + ALT"
---------------------
-- APPS / NOCTALIA
---------------------
local ipc = "noctalia msg "

-- Terminal
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd(terminal))
hl.bind(sharedMod .. " + RETURN", hl.dsp.exec_cmd(terminal))

-- File manager
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))

-- Noctalia launcher
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(ipc .. "panel-toggle launcher"))

-- Sidebar/notifications equivalent
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd(ipc .. "panel-toggle control-center notifications"))

-- Dashboard equivalent
hl.bind(mainMod .. " + D", hl.dsp.exec_cmd(ipc .. "panel-toggle control-center"))

-- Noctalia settings
hl.bind(mainMod .. " + comma", hl.dsp.exec_cmd(ipc .. "settings-toggle"))

-- Session / power menu
hl.bind(mainMod .. " + X", hl.dsp.exec_cmd(ipc .. "panel-toggle session"))

-- Lock
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd(ipc .. "session lock"))

-- Wallpaper picker
hl.bind(mainMod .. " + W", hl.dsp.exec_cmd(ipc .. "panel-toggle wallpaper"))

