-- WINDOWS
---------------------
-- Close active window

hl.bind(mainMod .. " + C", hl.dsp.window.close())
hl.bind(sharedMod .. " + SHIFT + Q", hl.dsp.window.close())

-- Toggle floating

hl.bind(
    mainMod .. " + V",
    hl.dsp.window.float({
        action = "toggle",
    })
)
hl.bind(
    sharedMod .. " + SHIFT + SPACE",
    hl.dsp.window.float({
        action = "toggle",
    })
)

-- Fullscreen
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen())
hl.bind(sharedMod .. " + F", hl.dsp.window.fullscreen())

-- Pseudo tiling
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())

-- Toggle dwindle split
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))

-- Center floating window
hl.bind(mainMod .. " + SHIFT + C", hl.dsp.window.center())
