-- FOCUS
---------------------
hl.bind(
    mainMod .. " + left",
    hl.dsp.focus({
        direction = "left",
    })
)

hl.bind(
    mainMod .. " + right",
    hl.dsp.focus({
        direction = "right",
    })
)

hl.bind(
    mainMod .. " + up",
    hl.dsp.focus({
        direction = "up",
    })
)

hl.bind(
    mainMod .. " + down",
    hl.dsp.focus({
        direction = "down",
    })
)

local sharedDirections = {
    h = "left",
    j = "down",
    k = "up",
    l = "right",
    left = "left",
    down = "down",
    up = "up",
    right = "right",
}

for key, direction in pairs(sharedDirections) do
    hl.bind(
        sharedMod .. " + " .. key,
        hl.dsp.focus({
            direction = direction,
        })
    )
end
---------------------
-- MOVE WINDOWS
---------------------
