    mainMod .. " + SHIFT + left",
    hl.dsp.window.move({
        direction = "left",
    })
)

hl.bind(
    mainMod .. " + SHIFT + right",
    hl.dsp.window.move({
        direction = "right",
    })
)

hl.bind(
    mainMod .. " + SHIFT + up",
    hl.dsp.window.move({
        direction = "up",
    })
)

hl.bind(
    mainMod .. " + SHIFT + down",
    hl.dsp.window.move({
        direction = "down",
    })
)

for key, direction in pairs(sharedDirections) do
    hl.bind(
        sharedMod .. " + SHIFT + " .. key,
        hl.dsp.window.move({
            direction = direction,
        })
    )
end

---------------------
-- WORKSPACES
---------------------
for i = 1, 10 do
    local key = i % 10
    hl.bind(
        mainMod .. " + " .. key,
        hl.dsp.focus({
            workspace = i,
        })
    )

    hl.bind(
        mainMod .. " + SHIFT + " .. key,
        hl.dsp.window.move({
            workspace = i,
        })
    )

    if i <= 9 then
        hl.bind(
            sharedMod .. " + " .. key,
            hl.dsp.focus({
                workspace = i,
            })
        )

        hl.bind(
            sharedMod .. " + SHIFT + " .. key,
            hl.dsp.window.move({
                workspace = i,
            })
        )
    end
end

