--------------------------------
---- NOCTALIA INTEGRATION ----
--------------------------------
-- Float the native Noctalia settings window.
hl.window_rule({
    name = "noctalia-settings",
    match = {
        class = "dev.noctalia.Noctalia",
    },
    float = true,
    size = { 1080, 920 },
})

-- Blur Noctalia surfaces in Hyprland and let Noctalia animate them itself.
hl.layer_rule({
    name = "noctalia",
    match = {
        namespace = "^noctalia-(bar-.+|notification|dock|panel|attached-panel|osd|window-switcher)$",
    },
    no_anim = true,
    ignore_alpha = 0.5,
    blur = true,
    blur_popups = true,
})

--------------------------------
---- WINDOWS AND WORKSPACES ----
--------------------------------
local suppressMaximizeRule = hl.window_rule({
    name = "suppress-maximize-events",
    match = {
        class = ".*",
    },
    suppress_event = "maximize",
})

---------------------
-- XWAYLAND FIX
---------------------
hl.window_rule({
    name = "fix-xwayland-drags",
    match = {
        class = "^$",
        title = "^$",
        xwayland = true,
        float = true,
        fullscreen = false,
        pin = false,
    },
    no_focus = true,
})

---------------------
-- HYPRLAND RUN
---------------------
hl.window_rule({
    name = "move-hyprland-run",
    match = {
        class = "hyprland-run",
    },
    move = "20 monitor_h-120",
    float = true,
})

---------------------
-- GUILD WARS 2
---------------------
hl.window_rule({
    name = "gw2-monitor",
    match = {
        class = "steam_app_1284210",
    },
    monitor = "DP-2",
})

hl.window_rule({
    name = "steam-games-idle-inhibit",
    match = {
        class = "^steam_app_.*$",
    },
    idle_inhibit = "fullscreen",
})


